// MinimockUpdateRangeInspect logs each unmet expectation
func (m *ParametersServiceMock) MinimockUpdateRangeInspect() {
	for _, e := range m.UpdateRangeMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to ParametersServiceMock.UpdateRange at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterUpdateRangeCounter := mm_atomic.LoadUint64(&m.afterUpdateRangeCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.UpdateRangeMock.defaultExpectation != nil && afterUpdateRangeCounter < 1 {
		if m.UpdateRangeMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to ParametersServiceMock.UpdateRange at\n%s", m.UpdateRangeMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to ParametersServiceMock.UpdateRange at\n%s with params: %#v", m.UpdateRangeMock.defaultExpectation.expectationOrigins.origin, *m.UpdateRangeMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcUpdateRange != nil && afterUpdateRangeCounter < 1 {
		m.t.Errorf("Expected call to ParametersServiceMock.UpdateRange at\n%s", m.funcUpdateRangeOrigin)
	}

	if !m.UpdateRangeMock.invocationsDone() && afterUpdateRangeCounter > 0 {
		m.t.Errorf("Expected %d calls to ParametersServiceMock.UpdateRange at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.UpdateRangeMock.expectedInvocations), m.UpdateRangeMock.expectedInvocationsOrigin, afterUpdateRangeCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *ParametersServiceMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockApplyToClassInspect()

			m.MinimockCreateRangeInspect()

			m.MinimockDeleteRangeInspect()

			m.MinimockExcludeFromClassInspect()

			m.MinimockListParametersInspect()

			m.MinimockUpdateRangeInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *ParametersServiceMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *ParametersServiceMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockApplyToClassDone() &&
		m.MinimockCreateRangeDone() &&
		m.MinimockDeleteRangeDone() &&
		m.MinimockExcludeFromClassDone() &&
		m.MinimockListParametersDone() &&
		m.MinimockUpdateRangeDone()
}
